// Package attribution recognizes the lines of a text that sign it in the name
// of a coding agent.
//
// A pull request merges by squash, and its title and body become the squash
// commit on the base branch. A coding agent, or the service that hosts it, can
// sign that text: a "Generated by" footer, a Co-Authored-By trailer for a
// model, a link to the agent's session. Once the commit is on the base branch,
// only a history rewrite removes the signature.
//
// A signature takes one of three forms, matched line by line and
// case-insensitively. A path such as .claude/ or .agents/, and a human
// co-author, are not signatures. The gate that judges a proposed squash
// message and the command that publishes a proposal read the same forms here,
// so the text one removes is the text the other refuses.
package attribution

import (
	"regexp"
	"strings"
)

// The kinds of signature a line carries.
const (
	// GeneratedFooter is "Generated by" or "Generated with" followed by an
	// agent's name, whatever the markup around it.
	GeneratedFooter = "generated-footer"
	// CoAuthorTrailer is a Co-Authored-By trailer whose name or address is an
	// agent's.
	CoAuthorTrailer = "co-author-trailer"
	// SessionLink is a link to an agent's session, or the trailer that
	// carries one.
	SessionLink = "session-link"
)

// agentNames lists the coding agents, their hosts and their vendors that a
// signature names. Each is matched as a whole word, case-insensitively.
const agentNames = `claude|anthropic|codex|openai|chatgpt|gpt-[0-9][a-z0-9.-]*|copilot|cursor|gemini|devin|windsurf|aider`

// signatures are the three forms, in the order a line is judged.
var signatures = []struct {
	kind    string
	pattern *regexp.Regexp
}{
	// No \b before "generated": the "_" of italics is a word character, and
	// _Generated by [Name](url)_ reads as one footer.
	{GeneratedFooter, regexp.MustCompile(`(?i)(?:^|[^a-z0-9])generated\s+(?:by|with)\s+[^a-z0-9\s]*(?:` + agentNames + `)\b`)},
	{CoAuthorTrailer, regexp.MustCompile(`(?i)^\s*co-authored-by:.*(?:\b(?:` + agentNames + `)\b|@(?:anthropic|openai)\.com)`)},
	{SessionLink, regexp.MustCompile(`(?i)claude\.ai/code/session_|chatgpt\.com/codex/|^\s*(?:` + agentNames + `)-session:`)},
}

// Line is one line of a text that signs it in the name of an agent.
type Line struct {
	// Line is the 1-based line number in the text.
	Line int `json:"line"`
	// Kind is GeneratedFooter, CoAuthorTrailer or SessionLink.
	Kind string `json:"kind"`
	// Text is the line, trimmed.
	Text string `json:"text"`
}

// Kind answers the form of signature line carries, and false when it carries
// none. line is one line, without its line break.
func Kind(line string) (string, bool) {
	for _, signature := range signatures {
		if signature.pattern.MatchString(line) {
			return signature.kind, true
		}
	}
	return "", false
}

// Find lists every line of text that carries a signature, in order. A CRLF
// line break reads as LF.
func Find(text string) []Line {
	var found []Line
	for i, line := range lines(text) {
		if kind, ok := Kind(line); ok {
			found = append(found, Line{Line: i + 1, Kind: kind, Text: strings.TrimSpace(line)})
		}
	}
	return found
}

// Names reports whether any line of text carries a signature.
func Names(text string) bool {
	for _, line := range lines(text) {
		if _, ok := Kind(line); ok {
			return true
		}
	}
	return false
}

// Strip removes every line of text that carries a signature and answers the
// rest with the lines it removed, numbered in the original text. A removal
// leaves no run of blank lines behind it, and the rest ends on its last line
// that is not blank; every other line stays as written. A text without a
// signature comes back unchanged, CRLF line breaks included.
func Strip(text string) (string, []Line) {
	removed := Find(text)
	if len(removed) == 0 {
		return text, nil
	}
	drop := make(map[int]bool, len(removed))
	for _, line := range removed {
		drop[line.Line] = true
	}
	var kept []string
	afterRemoval := false
	for i, line := range lines(text) {
		if drop[i+1] {
			afterRemoval = true
			continue
		}
		blank := strings.TrimSpace(line) == ""
		if blank && afterRemoval && (len(kept) == 0 || strings.TrimSpace(kept[len(kept)-1]) == "") {
			continue
		}
		afterRemoval = afterRemoval && blank
		kept = append(kept, line)
	}
	for len(kept) > 0 && strings.TrimSpace(kept[len(kept)-1]) == "" {
		kept = kept[:len(kept)-1]
	}
	return strings.Join(kept, "\n"), removed
}

func lines(text string) []string {
	return strings.Split(strings.ReplaceAll(text, "\r\n", "\n"), "\n")
}
